// Replace demo sources with local artwork paths. Width/height preserve the gallery layout.
const works = [
 {title:'ORBITAL STUDY',category:'POSTER / 001',width:700,height:880,colors:['#dc431e','#181815'],type:'orbit'},
 {title:'CHROME SIGNAL',category:'EXPERIMENT / 002',width:700,height:700,colors:['#aab9f2','#2020b5'],type:'chrome'},
 {title:'FORM / FREQUENCY',category:'TYPE STUDY / 003',width:700,height:940,colors:['#c6dd56','#1d271d'],type:'type'},
 {title:'AFTER HOURS',category:'POSTER / 004',width:700,height:850,colors:['#e4d8bf','#332440'],type:'waves'},
 {title:'OTHER WORLDS',category:'EXPERIMENT / 005',width:700,height:700,colors:['#2028ce','#e0f276'],type:'planet'},
 {title:'ECHO CHAMBER',category:'POSTER / 006',width:700,height:940,colors:['#201d1d','#f16a3c'],type:'echo'},
 {title:'SOFT STRUCTURE',category:'FORM STUDY / 007',width:700,height:700,colors:['#d1a4c9','#373e28'],type:'structure'},
 {title:'NO SIGNAL',category:'POSTER / 008',width:700,height:880,colors:['#cad4b9','#263d2c'],type:'signal'}
];
function demoArt(w,i){const [bg,fg]=w.colors,h=w.height;let art='';
 if(w.type==='orbit'){art=`<defs><radialGradient id="g"><stop stop-color="#ffe4bb"/><stop offset=".42" stop-color="#ed7042"/><stop offset="1" stop-color="#592718"/></radialGradient></defs><circle cx="350" cy="420" r="205" fill="url(#g)"/>`;for(let j=0;j<13;j++)art+=`<ellipse cx="350" cy="420" rx="${235+j*5}" ry="${40+j*8}" fill="none" stroke="${fg}" stroke-width="3" transform="rotate(-32 350 420)"/>`;art+='<text x="40" y="780" font-size="73" font-weight="900">ORBITAL</text><text x="44" y="818" font-size="18" letter-spacing="14">BEYOND THE ORDINARY</text>';}
 if(w.type==='chrome'){art='<defs><linearGradient id="g" x2="1" y2="1"><stop stop-color="#fff"/><stop offset=".25" stop-color="#687c96"/><stop offset=".48" stop-color="#f8ffff"/><stop offset=".52" stop-color="#151d37"/><stop offset=".8" stop-color="#ebfaff"/><stop offset="1" stop-color="#617a94"/></linearGradient></defs>';for(let j=0;j<5;j++)art+=`<rect x="${125+j*43}" y="${100+j*49}" width="280" height="280" rx="110" fill="none" stroke="url(#g)" stroke-width="48" transform="rotate(-28 350 350)"/>`;art+='<text x="30" y="660" font-size="19" letter-spacing="8">CHROME SIGNAL / VOL.02</text>';}
 if(w.type==='type'){art='<text x="34" y="105" font-size="19" letter-spacing="8">EXPERIMENTS IN PERCEPTION</text>';['F','O','R','M'].forEach((v,j)=>{art+=`<text x="${j%2?295:25}" y="${300+j*170}" font-size="260" font-weight="900" letter-spacing="-30">${v}${j%2?'':'/'}</text>`});art+='<text x="35" y="902" font-size="15" letter-spacing="6">SHAPE IS A LANGUAGE.</text>';}
 if(w.type==='waves'){for(let j=0;j<24;j++)art+=`<path d="M-50 ${140+j*22} Q180 ${-70+j*12} 350 ${350+j*14} T760 ${240+j*23}" stroke="${fg}" fill="none" stroke-width="7"/>`;art+='<text x="35" y="110" font-size="67" font-weight="900">AFTER HOURS</text><text x="40" y="799" font-size="17" letter-spacing="8">RHYTHMS WITHOUT SOUND</text>';}
 if(w.type==='planet'){art='<defs><radialGradient id="g" cx=".3" cy=".25"><stop stop-color="#e6faad"/><stop offset=".45" stop-color="#7dad58"/><stop offset="1" stop-color="#111544"/></radialGradient></defs><circle cx="350" cy="340" r="215" fill="url(#g)"/><ellipse cx="350" cy="340" rx="310" ry="72" transform="rotate(-25 350 340)" stroke="#d4eab0" stroke-width="19" fill="none"/><text x="35" y="640" font-size="48" font-weight="900">OTHER WORLDS</text>';}
 if(w.type==='echo'){for(let j=0;j<17;j++)art+=`<rect x="${32+j*16}" y="${130+j*19}" width="${636-j*32}" height="${680-j*38}" rx="${180-j*9}" fill="none" stroke="${fg}" stroke-width="6"/>`;art+='<text x="38" y="85" font-size="63" font-weight="900">ECHO CHAMBER</text><text x="40" y="900" font-size="16" letter-spacing="8">A STUDY IN REPETITION</text>';}
 if(w.type==='structure'){for(let j=0;j<7;j++)art+=`<rect x="${85+j*57}" y="${120+Math.sin(j)*65}" width="95" height="420" rx="47" fill="${fg}" transform="rotate(25 350 350)"/>`;art+='<text x="35" y="655" font-size="32" letter-spacing="5">SOFT STRUCTURE</text>';}
 if(w.type==='signal'){for(let j=0;j<55;j++)art+=`<path d="M50 ${160+j*10} Q${180+j*3} ${160+j*10-160*Math.sin(j/17)} 350 ${160+j*10} T650 ${160+j*10}" fill="none" stroke="${fg}" stroke-width="3"/>`;art+='<text x="32" y="100" font-size="75" font-weight="900">NO SIGNAL.</text><text x="38" y="820" font-size="19" letter-spacing="8">PLEASE STAY CONNECTED</text>';}
 return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="700" height="${h}" viewBox="0 0 700 ${h}"><rect width="700" height="${h}" fill="${bg}"/><g fill="${fg}" font-family="Arial,sans-serif">${art}</g><text x="30" y="${h-15}" fill="${fg}" font-family="monospace" font-size="9" letter-spacing="3">FOLIO — DEMO ARTWORK ${String(i+1).padStart(2,'0')}</text></svg>`);
}
const gallery=document.querySelector('#gallery'),viewer=document.querySelector('#viewer');let current=0,touchX=0;
works.forEach((work,i)=>{work.src=work.src||demoArt(work,i);const button=document.createElement('button');button.className='work';button.setAttribute('aria-label',`Powiększ: ${work.title}`);const meta=document.createElement('div');meta.className='work-meta';const title=document.createElement('span');title.textContent=work.title+'.svg';const number=document.createElement('span');number.textContent=String(i+1).padStart(2,'0');meta.append(title,number);const img=new Image(work.width,work.height);img.src=work.src;img.alt=work.title+' — grafika demonstracyjna';img.loading=i<3?'eager':'lazy';img.decoding='async';const bottom=document.createElement('div');bottom.className='work-bottom';const category=document.createElement('span');category.textContent=work.category;const arrow=document.createElement('span');arrow.textContent='↗';bottom.append(category,arrow);button.append(meta,img,bottom);button.addEventListener('click',()=>{current=i;updateViewer();viewer.showModal()});gallery.append(button)});
function updateViewer(){const w=works[current];document.querySelector('#viewerImage').src=w.src;document.querySelector('#viewerImage').alt=w.title+' — grafika demonstracyjna';document.querySelector('#viewerTitle').textContent=w.title;document.querySelector('#viewerCategory').textContent=w.category;document.querySelector('#viewerCount').textContent=`${String(current+1).padStart(2,'0')} / ${works.length}`}
function navigate(step){current=(current+step+works.length)%works.length;updateViewer()}
document.querySelector('#previous').onclick=()=>navigate(-1);document.querySelector('#next').onclick=()=>navigate(1);document.querySelector('#closeViewer').onclick=()=>viewer.close();viewer.addEventListener('click',e=>{if(e.target===viewer){const r=viewer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)viewer.close()}});viewer.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();navigate(1)}if(e.key==='ArrowLeft'){e.preventDefault();navigate(-1)}});viewer.addEventListener('touchstart',e=>{touchX=e.changedTouches[0].clientX},{passive:true});viewer.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-touchX;if(Math.abs(dx)>65)navigate(dx<0?1:-1)},{passive:true});
document.querySelectorAll('[data-density]').forEach(button=>button.addEventListener('click',()=>{gallery.classList.toggle('comfortable',button.dataset.density==='comfortable');document.querySelectorAll('[data-density]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))})}));
document.querySelector('#infoButton').onclick=function(){const expanded=this.getAttribute('aria-expanded')==='true';this.setAttribute('aria-expanded',String(!expanded));this.textContent=expanded?'[ INFO + ]':'[ INFO − ]';document.querySelector('#about').hidden=expanded};
document.querySelector('#year').textContent=new Date().getFullYear();document.querySelector('#workCount').textContent=String(works.length).padStart(2,'0')+' FILES FOUND';document.querySelector('#backTop').onclick=e=>{e.preventDefault();document.querySelector('#screen').scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})};
